import { error, parseReservationCommand, reservationResponse } from "./reservation";
import type {
  ProviderBInventoryRow,
  ProviderBReservationRow,
  ProviderBStorage,
  Reservation,
  Service,
  Stock,
} from "./types";
import {
  decodeCanonicalDecimal,
  decodeProviderBInventoryRow,
  decodeProviderBReservationRow,
  encodeCanonicalDecimal,
  isRecord,
  isRevision,
} from "./validation";

type ReadResult<T> =
  | Readonly<{ kind: "found"; value: T }>
  | Readonly<{ kind: "missing" }>
  | Readonly<{ kind: "unavailable" }>;

function providerInventoryToStock(row: ProviderBInventoryRow, requestedKey: string): Stock | undefined {
  const totalUnits = decodeCanonicalDecimal(row.onHandText);
  const reservedUnits = decodeCanonicalDecimal(row.heldText);
  const revision = decodeCanonicalDecimal(row.revisionText);
  if (row.itemKey !== requestedKey || totalUnits === undefined || reservedUnits === undefined ||
      revision === undefined) return undefined;
  return {
    sku: row.itemKey,
    totalUnits,
    reservedUnits,
    revision,
  };
}

function providerReservationToReservation(
  row: ProviderBReservationRow,
  requestedKey: string,
): Reservation | undefined {
  const quantity = decodeCanonicalDecimal(row.unitsText);
  if (row.bookingKey !== requestedKey || quantity === undefined) return undefined;
  return {
    reservationId: row.bookingKey,
    sku: row.itemKey,
    quantity,
  };
}

function decodeProviderEnvelope<T>(
  raw: unknown,
  decodeValue: (value: unknown) => T | undefined,
): ReadResult<T> {
  if (!isRecord(raw) || typeof raw.ok !== "boolean") return { kind: "unavailable" };
  if (raw.ok) {
    const value = decodeValue(raw.value);
    return value === undefined ? { kind: "unavailable" } : { kind: "found", value };
  }
  if (!isRecord(raw.error) || typeof raw.error.reason !== "string") {
    return { kind: "unavailable" };
  }
  if (raw.error.reason === "NO_SUCH_KEY") return { kind: "missing" };
  return { kind: "unavailable" };
}

async function readStock(storage: ProviderBStorage, sku: string): Promise<ReadResult<Stock>> {
  const envelope = await storage.read({ collection: "inventory", key: sku });
  const decoded = decodeProviderEnvelope(envelope, decodeProviderBInventoryRow);
  if (decoded.kind !== "found") return decoded;
  const stock = providerInventoryToStock(decoded.value, sku);
  return stock === undefined ? { kind: "unavailable" } : { kind: "found", value: stock };
}

async function readReservation(
  storage: ProviderBStorage,
  reservationId: string,
): Promise<ReadResult<Reservation>> {
  const envelope = await storage.read({ collection: "reservations", key: reservationId });
  const decoded = decodeProviderEnvelope(envelope, decodeProviderBReservationRow);
  if (decoded.kind !== "found") return decoded;
  const reservation = providerReservationToReservation(decoded.value, reservationId);
  return reservation === undefined ? { kind: "unavailable" } : { kind: "found", value: reservation };
}

export function createProviderBReservationService({ storage }: { storage: ProviderBStorage }): Service {
  return {
    async handle(raw) {
      const command = parseReservationCommand(raw);
      if (command === undefined) return error(400, "invalid_command");
      try {
        if (command.op === "getAvailability") {
          const stock = await readStock(storage, command.sku);
          if (stock.kind === "missing") return error(404, "stock_not_found");
          if (stock.kind === "unavailable") return error(500, "storage_unavailable");
          return {
            status: 200,
            body: {
              sku: stock.value.sku,
              totalUnits: stock.value.totalUnits,
              reservedUnits: stock.value.reservedUnits,
              availableUnits: stock.value.totalUnits - stock.value.reservedUnits,
            },
          };
        }

        const existing = await readReservation(storage, command.reservationId);
        if (existing.kind === "unavailable") return error(500, "storage_unavailable");
        if (command.op === "getReservation") {
          return existing.kind === "found"
            ? reservationResponse(200, existing.value)
            : error(404, "reservation_not_found");
        }
        if (existing.kind === "found") {
          return existing.value.sku === command.sku && existing.value.quantity === command.quantity
            ? reservationResponse(200, existing.value)
            : error(409, "reservation_conflict");
        }

        const stock = await readStock(storage, command.sku);
        if (stock.kind === "missing") return error(404, "stock_not_found");
        if (stock.kind === "unavailable") return error(500, "storage_unavailable");
        if (stock.value.totalUnits - stock.value.reservedUnits < command.quantity) {
          return error(409, "insufficient_stock");
        }

        const nextRevision = stock.value.revision + 1;
        if (!isRevision(nextRevision)) return error(500, "storage_unavailable");

        const reservation: Reservation = {
          reservationId: command.reservationId,
          sku: command.sku,
          quantity: command.quantity,
        };
        const outcome = await storage.commitBatch({
          expectedRevisionText: encodeCanonicalDecimal(stock.value.revision),
          stockRow: {
            itemKey: command.sku,
            onHandText: encodeCanonicalDecimal(stock.value.totalUnits),
            heldText: encodeCanonicalDecimal(stock.value.reservedUnits + command.quantity),
            revisionText: encodeCanonicalDecimal(nextRevision),
          },
          reservationRow: {
            bookingKey: command.reservationId,
            itemKey: command.sku,
            unitsText: encodeCanonicalDecimal(command.quantity),
          },
          outboxRows: [{
            key: "reservation.created:" + command.reservationId,
            category: "reservation",
            name: "created",
            payload: {
              bookingKey: command.reservationId,
              itemKey: command.sku,
              unitsText: encodeCanonicalDecimal(command.quantity),
            },
          }],
        });
        if (outcome === "revision_conflict") return error(409, "commit_conflict");
        if (outcome !== "applied") return error(500, "storage_unavailable");
        return reservationResponse(201, reservation);
      } catch {
        return error(500, "storage_unavailable");
      }
    },
  };
}

